import { DatePipe } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController } from '@ionic/angular';
import { G } from 'src/app/core/common/G';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { IProductCartHistoryDetailModel, IProductCartHistoryFilter, IProductCartHistoryModel, ProductCartHistoryFilter } from 'src/app/data/model/order/CartModel';
import { IAddOrUpdateProductModel } from 'src/app/data/model/product/AddOrUpdateProductModel';
import { IProductFilterModel, ProductFilterModel } from 'src/app/data/model/product/ProductFilterModel';
import { ProductService } from 'src/app/data/service/product/product.service';

@Component({
  selector: 'app-customers',
  templateUrl: './customers.component.html',
  styleUrls: ['./customers.component.scss']
})
export class CustomersComponent implements OnInit {

  selectedProductId = 0;
  productSelected = false;
  cartHistorySelected = false;
  filteredProducts: IProductFilterModel;
  productCategoryIds: number[] = [];
  mechanicCategories = [];
  tuningCategories = [];
  designeCategories = [];
  cartHistoryDetail: IProductCartHistoryDetailModel;
  productCartHistoryFilter: IProductCartHistoryFilter;
  empty = false;
  searchTitle = '';
  totalOrder = 0;
  searchIdValue = '1';
  searchTitle2 = '';
  sellCount = -1;
  sellPriceCount = -1;

  product: IAddOrUpdateProductModel;

  constructor(
    private productService: ProductService,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private activatedRoute: ActivatedRoute,
    public datepipe: DatePipe,
    private router: Router
  ) { }

  ngOnInit(): void {

    this.mechanicCategories = [];
    this.tuningCategories = [];
    this.designeCategories = [];

    G.getCourseCategory().subscribe(
      res => {

        if (res != null) {
          if (res.length > 0) {
            res.forEach(c => {

              if (c.parentId == 1) {
                this.mechanicCategories.push(c);
              } else if (c.parentId == 2) {
                this.tuningCategories.push(c);
              } else if (c.parentId == 3) {
                this.designeCategories.push(c);
              }
            });
          }
        }
      }
    );

    let filter: IProductFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page;
      const take = params.take ? params.take : 12;
      const title = params.title ? params.title : null;
      const startPrice = params.startPrice ? params.startPrice : null;
      const endPrice = params.endPrice ? params.endPrice : null;
      const categoryIds = params.categoryIds ? params.categoryIds : [];
      const sortId = params.sortId ? params.sortId : 4;

      if (page === undefined) {
        filter = new ProductFilterModel(false, page, take, title);
      } else {
        if (
          startPrice == null &&
          endPrice == null &&
          categoryIds == null &&
          sortId == null) {

          filter = new ProductFilterModel(false, page, take, title);
        } else {
          filter =
            new ProductFilterModel(true, page, take, title, startPrice, endPrice, categoryIds, sortId);
        }
      }
      this.filteredProducts = filter;

      SharedIonic.loading(this.loadingController);

      this.productService.GetSellerProductsByFilter(filter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            this.filteredProducts = res.data;
          } else {
            this.empty = true;
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    });
  }

  onBack() {

    this.productSelected = false;
  }

  onBack2() {

    this.cartHistorySelected = false;
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= +pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredProducts.startPage == null) {
      return;
    }
    if (this.filteredProducts.pageId > this.filteredProducts.startPage && +this.filteredProducts.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredProducts.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredProducts.endPage == null) {
      return;
    }
    if (this.filteredProducts.pageId < this.filteredProducts.endPage) {
      this.setQueryParams(+this.filteredProducts.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }


  goPreviousPage2() {

    if (this.productCartHistoryFilter.startPage == null) {
      return;
    }
    if (this.productCartHistoryFilter.pageId > this.productCartHistoryFilter.startPage && +this.productCartHistoryFilter.pageId - 1 > 0) {
      this.setQueryParams2(+this.productCartHistoryFilter.pageId - 1);
    }
  }

  goNextPage2() {

    if (this.productCartHistoryFilter.endPage == null) {
      return;
    }
    if (this.productCartHistoryFilter.pageId < this.productCartHistoryFilter.endPage) {
      this.setQueryParams2(+this.productCartHistoryFilter.pageId + 1);
    }
  }

  goPage2(pageId: number | string) {
    this.setQueryParams2(+pageId);
  }

  getSellCount() {

    this.productService.GetProductSellCount(
      this.selectedProductId
    ).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {
          this.sellCount = res.data;
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  getSellPriceCount() {

    this.productService.GetProductSellPriceCount(
      this.selectedProductId
    ).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {
          this.sellPriceCount = res.data;
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  getTime(date: Date): string {

    return this.datepipe.transform(date, 'HH:mm:ss');
  }

  setQueryParams2(pageId: number) {

    SharedIonic.loading(this.loadingController);

    this.productService.GetProductCartHistoryByFilter(
      new ProductCartHistoryFilter(
        this.selectedProductId,
        pageId,
        10,
        +this.searchIdValue,
        this.searchTitle2
      )
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.totalOrder = 0;

          this.productCartHistoryFilter = res.data;

          this.productCartHistoryFilter.productCartHistory.forEach(cart => {

            this.totalOrder += this.calculateTotalorder(cart);
          });

          this.productSelected = true;
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  setQueryParams(pageId: number) {

    this.filteredProducts.title = this.searchTitle;

    this.router
      .navigate(
        ['SellerPanel', 'Customers'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredProducts.takeEntity ? this.filteredProducts.takeEntity : null,
            title: this.filteredProducts.title ? this.filteredProducts.title : null,
            startPrice: this.filteredProducts.startPrice ? this.filteredProducts.startPrice : null,
            endPrice: this.filteredProducts.endPrice ? this.filteredProducts.endPrice : null,
            categoryIds: this.filteredProducts.categoryIds ? this.filteredProducts.categoryIds : [],
            sortId: this.filteredProducts.sortId ? this.filteredProducts.sortId : 0
          }
        });
  }

  onSelectItem(id: number | string) {

    this.selectedProductId = +id;
    this.sellCount = -1;
    this.sellPriceCount = -1;

    SharedIonic.loading(this.loadingController);

    this.productService.GetProductCartHistoryByFilterFirstTime(
      new ProductCartHistoryFilter(
        +id,
        1
      )
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.totalOrder = 0;
          this.productCartHistoryFilter = res.data;

          this.productCartHistoryFilter.productCartHistory.forEach(cart => {

            this.totalOrder += this.calculateTotalorder(cart);
          });

          this.productSelected = true;
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );

    this.getSellCount();
    this.getSellPriceCount();
  }

  calculateTotalorder(model: IProductCartHistoryModel): number {

    if (model.offCodePercent != 0) {
      return (model.price - ((model.price * model.offCodePercent) / 100));
    } else {
      if (model.offPrice != 0) {
        return model.offPrice;
      } else {
        return model.price;
      }
    }
  }

  calculateTotalPrice(): number {

    if (this.cartHistoryDetail.offCodePercent != 0) {
      return (this.cartHistoryDetail.price - ((this.cartHistoryDetail.price * this.cartHistoryDetail.offCodePercent) / 100));
    } else {
      if (this.cartHistoryDetail.offPrice != 0) {
        return this.cartHistoryDetail.offPrice;
      } else {
        return this.cartHistoryDetail.price;
      }
    }
  }

  onSelectCartHistory(id: number | string) {

    SharedIonic.loading(this.loadingController);

    this.productService.GetProductCartHistoryDetail(+id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.cartHistoryDetail = res.data;
          this.cartHistorySelected = true;
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }
}
